export const envelope = [26, 44, 28];

export default function build(api) {
  const [W, H, D] = api.size;

  // Theme & Material Palette
  const quartzSmooth = "minecraft:smooth_quartz";
  const quartzBlock = api.theme.stone.primary || "minecraft:quartz_block";
  const quartzPillar = "minecraft:quartz_pillar";
  const quartzChiseled = "minecraft:chiseled_quartz_block";
  const quartzStairs = api.theme.stone.stairs || "minecraft:quartz_stairs";
  const quartzSlab = api.theme.stone.slab || "minecraft:quartz_slab";
  const plinth = api.theme.ground.plinth || "minecraft:chiseled_quartz_block";
  const gold = "minecraft:gold_block";
  const gildedBlackstone = "minecraft:gilded_blackstone";
  const seaLantern = "minecraft:sea_lantern";
  const lapis = "minecraft:lapis_block";
  const amethyst = "minecraft:amethyst_block";

  // Voxel Grid Buffer with Priority Layering
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Array(D).fill(null))
  );
  const prio = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Int16Array(D).fill(-1))
  );

  function setVoxel(x, y, z, block, p = 10) {
    const ix = Math.floor(x), iy = Math.floor(y), iz = Math.floor(z);
    if (ix < 0 || ix >= W || iy < 0 || iy >= H || iz < 0 || iz >= D) return;
    if (p >= prio[ix][iy][iz]) {
      prio[ix][iy][iz] = p;
      grid[ix][iy][iz] = block;
    }
  }

  function fillCapsule(x1, y1, z1, x2, y2, z2, r1, r2, block, p = 20) {
    const minX = Math.max(0, Math.floor(Math.min(x1, x2) - Math.max(r1, r2) - 1));
    const maxX = Math.min(W - 1, Math.ceil(Math.max(x1, x2) + Math.max(r1, r2) + 1));
    const minY = Math.max(0, Math.floor(Math.min(y1, y2) - Math.max(r1, r2) - 1));
    const maxY = Math.min(H - 1, Math.ceil(Math.max(y1, y2) + Math.max(r1, r2) + 1));
    const minZ = Math.max(0, Math.floor(Math.min(z1, z2) - Math.max(r1, r2) - 1));
    const maxZ = Math.min(D - 1, Math.ceil(Math.max(z1, z2) + Math.max(r1, r2) + 1));

    const dx = x2 - x1, dy = y2 - y1, dz = z2 - z1;
    const lenSq = dx * dx + dy * dy + dz * dz;

    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          let t = 0;
          if (lenSq > 0.0001) {
            t = ((x - x1) * dx + (y - y1) * dy + (z - z1) * dz) / lenSq;
            t = Math.max(0, Math.min(1, t));
          }
          const px = x1 + t * dx;
          const py = y1 + t * dy;
          const pz = z1 + t * dz;
          const curR = r1 + t * (r2 - r1);
          const distSq = (x - px) * (x - px) + (y - py) * (y - py) + (z - pz) * (z - pz);
          if (distSq <= curR * curR) {
            setVoxel(x, y, z, block, p);
          }
        }
      }
    }
  }

  function fillEllipsoid(cx, cy, cz, rx, ry, rz, block, p = 20) {
    const minX = Math.max(0, Math.floor(cx - rx - 1));
    const maxX = Math.min(W - 1, Math.ceil(cx + rx + 1));
    const minY = Math.max(0, Math.floor(cy - ry - 1));
    const maxY = Math.min(H - 1, Math.ceil(cy + ry + 1));
    const minZ = Math.max(0, Math.floor(cz - rz - 1));
    const maxZ = Math.min(D - 1, Math.ceil(cz + rz + 1));

    for (let x = minX; x <= maxX; x++) {
      const nx = (x - cx) / rx;
      for (let y = minY; y <= maxY; y++) {
        const ny = (y - cy) / ry;
        for (let z = minZ; z <= maxZ; z++) {
          const nz = (z - cz) / rz;
          if (nx * nx + ny * ny + nz * nz <= 1.0) {
            setVoxel(x, y, z, block, p);
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 1. PEDESTAL & SANCTUARY VAULT (Y: 0 to 8)
  // -------------------------------------------------------------
  function isPedestalBase(x, z) {
    const dx = Math.abs(x - 13);
    const dz = Math.abs(z - 16);
    return (dx <= 9 && dz <= 10.5 && (dx + dz <= 16));
  }

  function isPedestalCore(x, z) {
    const dx = Math.abs(x - 13);
    const dz = Math.abs(z - 16);
    return (dx <= 8 && dz <= 9.5 && (dx + dz <= 14));
  }

  // Base tier 0: Plinth footprint
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (isPedestalBase(x, z)) {
        setVoxel(x, 0, z, plinth, 10);
      }
    }
  }

  // Pedestal body & interior vault (Y: 1 to 8)
  for (let y = 1; y <= 8; y++) {
    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        if (!isPedestalCore(x, z)) continue;

        const dx = Math.abs(x - 13);
        const dz = Math.abs(z - 16);
        const isCorner = (dx + dz >= 13);
        const isPerimeter = (dx >= 7 || dz >= 8.5 || isCorner);

        // Vault Interior Clearance (Y: 1 to 5)
        if (y >= 1 && y <= 5 && dx <= 3 && dz <= 4) {
          // Hollow interior for vault
          continue;
        }

        // Vault Portal Facing North (Z: 6..7) and South (Z: 25..26)
        if (y >= 1 && y <= 3 && dx <= 1 && (z <= 8 || z >= 24)) {
          continue;
        }

        if (y === 1) {
          setVoxel(x, y, z, isPerimeter ? quartzChiseled : quartzSmooth, 10);
        } else if (y === 2) {
          setVoxel(x, y, z, isCorner ? quartzPillar : quartzBlock, 10);
        } else if (y === 3) {
          // Inlaid gold runic band
          setVoxel(x, y, z, isPerimeter ? gold : quartzBlock, 12);
        } else if (y === 4) {
          setVoxel(x, y, z, isCorner ? quartzPillar : quartzSmooth, 10);
        } else if (y === 5) {
          setVoxel(x, y, z, isPerimeter ? quartzChiseled : quartzBlock, 10);
        } else if (y === 6) {
          // Vault ceiling course
          setVoxel(x, y, z, quartzBlock, 10);
        } else if (y === 7) {
          // Stepped capital cornice
          setVoxel(x, y, z, isPerimeter ? gold : quartzSmooth, 12);
        } else if (y === 8) {
          // Pedestal deck
          setVoxel(x, y, z, (dx <= 1 || dz <= 1) ? gold : quartzSmooth, 12);
        }
      }
    }
  }

  // Vault Central Arcane Relic
  setVoxel(13, 1, 16, seaLantern, 15);
  setVoxel(13, 2, 16, amethyst, 15);

  // Vault Corner Columns
  for (const cx of [10, 16]) {
    for (const cz of [12, 20]) {
      for (let y = 1; y <= 5; y++) {
        setVoxel(cx, y, cz, quartzPillar, 14);
      }
    }
  }

  // Pedestal Front Defiant Sunburst Crest (North face Z=7, Y=3..5)
  setVoxel(13, 4, 7, seaLantern, 16);
  setVoxel(12, 4, 7, gold, 16);
  setVoxel(14, 4, 7, gold, 16);
  setVoxel(13, 5, 7, gold, 16);
  setVoxel(13, 3, 7, gold, 16);

  // -------------------------------------------------------------
  // 2. UNICORN STATUE ANATOMY (Y: 7 to 43)
  // -------------------------------------------------------------

  // Pelvis, Haunches & Mid-Torso
  fillCapsule(13, 15.0, 20.0, 13, 18.5, 17.5, 3.8, 3.6, quartzSmooth, 20);
  fillCapsule(13, 18.5, 17.5, 13, 23.5, 13.5, 3.6, 4.0, quartzSmooth, 20);

  // Broad Chest & Pectorals
  fillCapsule(13, 23.5, 13.5, 13, 27.5, 10.0, 4.0, 4.4, quartzSmooth, 20);
  fillEllipsoid(13, 26.5, 9.8, 4.2, 3.8, 2.8, quartzBlock, 21);

  // Sol-Invictus Chest Medallion (Facing -Z toward pirate haven)
  setVoxel(13, 26, 7, seaLantern, 45);
  setVoxel(12, 26, 7, gold, 45);
  setVoxel(14, 26, 7, gold, 45);
  setVoxel(13, 27, 7, gold, 45);
  setVoxel(13, 25, 7, gold, 45);

  // Withers & Neck Arch
  fillCapsule(13, 27.0, 10.5, 13, 31.5, 8.0, 3.5, 2.8, quartzSmooth, 20);
  fillCapsule(13, 31.5, 8.0, 13, 35.5, 5.5, 2.8, 2.2, quartzSmooth, 20);

  // Equine Head & Cranium
  fillEllipsoid(13, 36.0, 5.2, 2.2, 2.0, 2.4, quartzSmooth, 22);
  fillEllipsoid(11.5, 35.2, 5.6, 1.2, 1.3, 1.3, quartzBlock, 22);
  fillEllipsoid(14.5, 35.2, 5.6, 1.2, 1.3, 1.3, quartzBlock, 22);

  // Muzzle & Snout
  fillCapsule(13, 35.2, 4.5, 13, 34.0, 2.2, 1.6, 1.1, quartzSmooth, 22);
  setVoxel(12.3, 33.8, 1.9, quartzChiseled, 24); // Left nostril
  setVoxel(13.7, 33.8, 1.9, quartzChiseled, 24); // Right nostril
  setVoxel(13.0, 33.2, 2.2, gold, 24); // Golden bridle ring

  // Arcane Eyes (Glowing cyan / lapis stare across the contested waters)
  setVoxel(11, 36, 4, seaLantern, 40);
  setVoxel(11, 36, 5, lapis, 40);
  setVoxel(15, 36, 4, seaLantern, 40);
  setVoxel(15, 36, 5, lapis, 40);

  // Pointed Ears
  fillCapsule(11.8, 37.2, 5.5, 11.2, 40.5, 6.2, 0.9, 0.3, quartzSmooth, 25);
  fillCapsule(14.2, 37.2, 5.5, 14.8, 40.5, 6.2, 0.9, 0.3, quartzSmooth, 25);

  // -------------------------------------------------------------
  // 3. THE COLOSSAL ALICORN (HORN) (Y: 37 to 43, facing North -Z)
  // -------------------------------------------------------------
  const hornPoints = [
    { x: 13.0, y: 37.5, z: 3.8, r: 1.2, b: gold },
    { x: 13.0, y: 38.4, z: 3.1, r: 1.0, b: seaLantern },
    { x: 13.0, y: 39.3, z: 2.4, r: 0.9, b: gold },
    { x: 13.0, y: 40.2, z: 1.7, r: 0.7, b: quartzSmooth },
    { x: 13.0, y: 41.1, z: 1.0, r: 0.5, b: seaLantern },
    { x: 13.0, y: 42.0, z: 0.4, r: 0.3, b: gold },
  ];

  for (let i = 0; i < hornPoints.length - 1; i++) {
    const p1 = hornPoints[i];
    const p2 = hornPoints[i + 1];
    fillCapsule(p1.x, p1.y, p1.z, p2.x, p2.y, p2.z, p1.r, p2.r, p1.b, 50);
  }

  // -------------------------------------------------------------
  // 4. HIND LEGS & STRUCTURAL BASE ANCHOR
  // -------------------------------------------------------------
  // Left Hind Leg
  fillCapsule(9.5, 17.0, 19.5, 9.5, 13.0, 21.0, 2.4, 2.0, quartzSmooth, 20);
  fillCapsule(9.5, 13.0, 21.0, 9.5, 10.0, 21.8, 2.0, 1.6, quartzSmooth, 20);
  fillCapsule(9.5, 10.0, 21.8, 9.5, 8.0, 19.5, 1.6, 1.4, quartzSmooth, 20);
  fillCapsule(9.5, 8.0, 19.5, 9.5, 7.5, 19.0, 1.5, 1.6, gildedBlackstone, 35);
  fillCapsule(9.5, 7.5, 19.0, 9.5, 7.0, 18.5, 1.6, 1.8, gold, 36);

  // Right Hind Leg
  fillCapsule(16.5, 17.0, 19.5, 16.5, 13.0, 21.0, 2.4, 2.0, quartzSmooth, 20);
  fillCapsule(16.5, 13.0, 21.0, 16.5, 10.0, 21.8, 2.0, 1.6, quartzSmooth, 20);
  fillCapsule(16.5, 10.0, 21.8, 16.5, 8.0, 19.5, 1.6, 1.4, quartzSmooth, 20);
  fillCapsule(16.5, 8.0, 19.5, 16.5, 7.5, 19.0, 1.5, 1.6, gildedBlackstone, 35);
  fillCapsule(16.5, 7.5, 19.0, 16.5, 7.0, 18.5, 1.6, 1.8, gold, 36);

  // Massive Sweeping Structural Tail (Forms 3-point base with hind hooves)
  fillCapsule(13.0, 17.5, 22.5, 13.0, 14.5, 24.2, 1.7, 1.9, quartzSmooth, 20);
  fillCapsule(13.0, 14.5, 24.2, 13.0, 11.0, 25.0, 1.9, 2.2, quartzSmooth, 20);
  fillCapsule(13.0, 11.0, 25.0, 13.0, 8.0, 24.2, 2.2, 2.5, quartzSmooth, 20);

  // Tail Radiant Streaks & Pedestal Integration
  fillCapsule(11.8, 12.0, 24.8, 11.5, 8.0, 23.5, 1.1, 1.3, gold, 30);
  fillCapsule(14.2, 12.0, 24.8, 14.5, 8.0, 23.5, 1.1, 1.3, gold, 30);
  fillCapsule(13.0, 13.0, 25.2, 13.0, 9.0, 25.0, 1.2, 1.4, seaLantern, 30);

  // -------------------------------------------------------------
  // 5. REARING FRONT FORELEGS
  // -------------------------------------------------------------
  // Left Foreleg (Striking forward/upward)
  fillCapsule(10.0, 25.5, 11.5, 9.2, 28.5, 8.0, 2.1, 1.6, quartzSmooth, 20);
  fillCapsule(9.2, 28.5, 8.0, 8.2, 31.5, 5.5, 1.6, 1.3, quartzSmooth, 20);
  fillCapsule(8.2, 31.5, 5.5, 7.8, 32.5, 4.8, 1.4, 1.5, gildedBlackstone, 35);
  fillCapsule(7.8, 32.5, 4.8, 7.5, 33.2, 4.2, 1.5, 1.6, gold, 36);

  // Right Foreleg (Reaching high toward the strait)
  fillCapsule(16.0, 25.5, 11.5, 16.8, 29.0, 8.5, 2.1, 1.6, quartzSmooth, 20);
  fillCapsule(16.8, 29.0, 8.5, 17.8, 33.0, 6.5, 1.6, 1.3, quartzSmooth, 20);
  fillCapsule(17.8, 33.0, 6.5, 18.2, 34.0, 5.8, 1.4, 1.5, gildedBlackstone, 35);
  fillCapsule(18.2, 34.0, 5.8, 18.5, 34.8, 5.2, 1.5, 1.6, gold, 36);

  // -------------------------------------------------------------
  // 6. CELESTIAL FLOWING MANE & WING CRESTS
  // -------------------------------------------------------------
  // Radiant Mane Crest along neck spine
  fillCapsule(13.0, 28.0, 12.0, 13.0, 31.0, 10.0, 1.2, 1.4, gold, 30);
  fillCapsule(13.0, 31.0, 10.0, 13.0, 34.0, 8.0, 1.3, 1.3, seaLantern, 30);
  fillCapsule(13.0, 34.0, 8.0, 13.0, 37.0, 6.2, 1.2, 1.1, gold, 30);

  // Billowing mane locks
  fillCapsule(11.5, 32.5, 9.0, 10.5, 29.5, 11.0, 0.9, 0.7, quartzBlock, 28);
  fillCapsule(14.5, 33.0, 8.5, 15.5, 30.0, 10.5, 0.9, 0.7, quartzBlock, 28);
  fillCapsule(11.0, 35.0, 7.5, 9.8, 32.5, 9.5, 0.8, 0.6, gold, 30);
  fillCapsule(15.0, 35.5, 7.0, 16.2, 33.0, 9.0, 0.8, 0.6, gold, 30);

  // Arcane Folded Wing Crests along flanks
  // Left Wing Crest
  fillCapsule(9.0, 26.5, 11.5, 6.5, 24.0, 15.0, 1.5, 1.2, quartzSmooth, 25);
  fillCapsule(6.5, 24.0, 15.0, 5.5, 20.5, 19.0, 1.2, 0.9, gold, 26);
  fillCapsule(7.5, 25.0, 13.5, 6.5, 22.0, 17.0, 1.1, 0.8, quartzBlock, 25);

  // Right Wing Crest
  fillCapsule(17.0, 26.5, 11.5, 19.5, 24.0, 15.0, 1.5, 1.2, quartzSmooth, 25);
  fillCapsule(19.5, 24.0, 15.0, 20.5, 20.5, 19.0, 1.2, 0.9, gold, 26);
  fillCapsule(18.5, 25.0, 13.5, 19.5, 22.0, 17.0, 1.1, 0.8, quartzBlock, 25);

  // -------------------------------------------------------------
  // 7. EMIT VOXELS & APPLY GROUND CONFORMANCE (Rule 6)
  // -------------------------------------------------------------
  // Emit buffered colossus and pedestal voxels
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const blk = grid[x][y][z];
        if (blk !== null) {
          api.set(x, y, z, blk);
        }
      }
    }
  }

  // Terrain skirt & footing down to api.heightAt(x, z)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (isPedestalBase(x, z)) {
        const gh = api.heightAt(x, z);
        const startY = Math.min(0, Math.floor(gh));
        for (let y = startY; y <= 0; y++) {
          api.set(x, y, z, plinth);
        }
        // If terrain rises above seat plane (y > 0), anchor firmly
        if (gh > 0) {
          const topH = Math.min(H - 1, Math.floor(gh));
          for (let y = 1; y <= topH; y++) {
            if (grid[x][y][z] === null) {
              api.set(x, y, z, plinth);
            }
          }
        }
      }
    }
  }

  return {
    name: "unicorn_colossus",
    seatY: 0,
    anchors: {
      front: [13, 1, 0],       // Defiant gaze facing North across the strait
      pedestal: [13, 8, 16],
      horn: [13, 42, 1],
    },
    interiors: [
      {
        min: [10, 1, 12],
        max: [16, 5, 20],
        kind: "vault",
      },
    ],
  };
}

