export const envelope = [27, 38, 56];

export default function build(api) {
  const [W, H, D] = api.size;

  // Theme-derived wooden palette
  const woodPlanks = api.theme.wood.planks;
  const woodLog = api.theme.wood.log;
  const woodStripped = api.theme.wood.stripped;
  const woodStairs = api.theme.wood.stairs;
  const woodSlab = api.theme.wood.slab;
  const woodFence = api.theme.wood.fence;
  const woodTrapdoor = api.theme.wood.trapdoor;
  const woodDoor = api.theme.wood.door;

  // Nautical & warfare materials
  const darkPlanks = "minecraft:dark_oak_planks";
  const darkLog = "minecraft:dark_oak_log";
  const darkFence = "minecraft:dark_oak_fence";
  const darkSlab = "minecraft:dark_oak_slab";
  const darkStairs = "minecraft:dark_oak_stairs";
  const darkTrapdoor = "minecraft:dark_oak_trapdoor";
  const sprucePlanks = "minecraft:spruce_planks";
  const spruceFence = "minecraft:spruce_fence";

  const ironBars = "minecraft:iron_bars";
  const chain = "minecraft:chain";
  const lantern = "minecraft:lantern";
  const hangLantern = "minecraft:lantern[hanging=true]";
  const dispenserWest = "minecraft:dispenser[facing=west]";
  const dispenserEast = "minecraft:dispenser[facing=east]";
  const blackWool = "minecraft:black_wool";
  const grayWool = "minecraft:gray_wool";
  const redWool = "minecraft:red_wool";
  const boneBlock = "minecraft:bone_block";
  const goldBlock = "minecraft:gold_block";
  const polishedBlackstone = "minecraft:polished_blackstone";
  const skull = "minecraft:skeleton_skull";
  const ladderNorth = "minecraft:ladder[facing=north]";
  const ladderSouth = "minecraft:ladder[facing=south]";
  const redBannerNorth = "minecraft:red_banner[rotation=0]";
  const redBannerSouth = "minecraft:red_banner[rotation=8]";
  const blackBannerNorth = "minecraft:black_banner[rotation=0]";

  const seatY = 6;
  const midX = 13;

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // --- Hull Geometry Functions ---
  function getYBot(z) {
    if (z < 10 || z > 52) return 99;
    if (z === 10) return 11;
    if (z === 11) return 9;
    if (z === 12) return 8;
    if (z === 13) return 7;
    if (z <= 48) return 6;
    if (z <= 50) return 7;
    if (z === 51) return 8;
    return 9;
  }

  function getYRail(z) {
    if (z < 10 || z > 52) return -1;
    if (z <= 18) return 16; // Forecastle
    if (z <= 36) return 13; // Waist deck
    if (z <= 44) return 16; // Quarterdeck
    return 20;             // Sterncastle / Poop deck
  }

  function getHullRadius(y, z) {
    if (z < 10 || z > 52) return -1;
    const yb = getYBot(z);
    const yr = getYRail(z);
    if (y < yb || y > yr) return -1;

    let maxB;
    if (z <= 18) {
      maxB = 0.6 + 3.6 * Math.sin(((z - 10) / 8) * (Math.PI / 2));
    } else if (z <= 38) {
      maxB = 4.2 + 1.1 * Math.sin(((z - 18) / 20) * Math.PI);
    } else {
      maxB = 5.3 - 1.8 * Math.pow((z - 38) / 14, 1.2);
    }

    const yRel = y - yb;
    let vFactor;
    if (yRel <= 2) {
      vFactor = 0.35 + 0.45 * (yRel / 2);
    } else if (yRel <= 5) {
      vFactor = 0.8 + 0.2 * ((yRel - 2) / 3);
    } else {
      if (z >= 44 || z <= 18) {
        vFactor = 1.0;
      } else {
        vFactor = 1.0 - 0.08 * Math.min(1, (yRel - 5) / 3);
      }
    }

    return maxB * vFactor;
  }

  // --- 1. Terrain Conformance & Submerged Hull Footing ---
  for (let z = 10; z <= 52; z++) {
    const yb = getYBot(z);
    const rad = getHullRadius(yb, z);
    const rInt = Math.ceil(Math.max(0, rad));
    for (let x = midX - rInt; x <= midX + rInt; x++) {
      const hGround = Math.floor(api.heightAt(x, z));
      const gY = Math.max(0, Math.min(seatY, seatY + hGround));
      for (let y = gY; y < yb; y++) {
        setBlock(x, y, z, (x === midX || y === yb - 1) ? darkLog : woodPlanks);
      }
    }
  }

  // Mooring Pilings / Harbor Dolphins
  function buildMooringPiling(px, pz, topY) {
    const hGround = Math.floor(api.heightAt(px, pz));
    const gY = Math.max(0, Math.min(seatY, seatY + hGround));
    for (let y = gY; y <= topY; y++) {
      setBlock(px, y, pz, darkLog);
      setBlock(px + 1, y, pz, darkLog);
      setBlock(px, y, pz + 1, darkLog);
      setBlock(px + 1, y, pz + 1, darkLog);
    }
    setBlock(px, topY + 1, pz, darkFence);
    setBlock(px + 1, topY + 1, pz, darkFence);
    setBlock(px, topY + 1, pz + 1, darkFence);
    setBlock(px + 1, topY + 1, pz + 1, darkFence);
    setBlock(px, topY + 2, pz, hangLantern);
  }

  buildMooringPiling(3, 24, 11);
  buildMooringPiling(22, 34, 11);

  // Mooring chains from pilings to ship's hull
  for (let cx = 4; cx <= 8; cx++) {
    setBlock(cx, 11, 24, chain);
  }
  for (let cx = 18; cx <= 22; cx++) {
    setBlock(cx, 11, 34, chain);
  }

  // --- 2. Hull Shell, Ribs, and Decks ---
  for (let z = 10; z <= 52; z++) {
    const yb = getYBot(z);
    const yr = getYRail(z);

    for (let y = yb; y <= yr; y++) {
      const rOuter = getHullRadius(y, z);
      if (rOuter < 0) continue;

      const rFloor = Math.max(0, rOuter - 1.05);

      for (let x = midX - Math.ceil(rOuter); x <= midX + Math.ceil(rOuter); x++) {
        const dx = Math.abs(x - midX);

        if (dx <= rOuter) {
          const isOuterWall = dx >= rFloor;
          const isRib = (z % 3 === 0) || (y === yb) || (y === 9) || (y === 13);

          if (isOuterWall) {
            // Hull outer wall
            if (y === yr) {
              // Top bulwark railing
              setBlock(x, y, z, (dx > rFloor + 0.3) ? darkFence : darkPlanks);
            } else {
              setBlock(x, y, z, isRib ? darkLog : woodPlanks);
            }
          } else {
            // Interior decks & bulkheads
            // Deck heights: Hold=6, GunDeck=10, Waist=11, Forecastle/Quarter=14, Poop=18
            let isDeck = false;
            let deckBlock = woodPlanks;

            if (y === 6 && z >= 14 && z <= 48) {
              isDeck = true;
              deckBlock = darkPlanks;
            } else if (y === 10 && z >= 14 && z <= 50) {
              isDeck = true;
              deckBlock = woodPlanks;
            } else if (y === 11 && z >= 19 && z <= 36) {
              isDeck = true;
              deckBlock = sprucePlanks;
            } else if (y === 14 && ((z >= 11 && z <= 18) || (z >= 37 && z <= 51))) {
              isDeck = true;
              deckBlock = darkPlanks;
            } else if (y === 18 && z >= 45 && z <= 51) {
              isDeck = true;
              deckBlock = sprucePlanks;
            }

            // Bulkheads
            if (z === 18 && y >= 11 && y <= 13) {
              isDeck = true;
              deckBlock = woodStripped;
            }
            if (z === 36 && y >= 11 && y <= 13) {
              isDeck = true;
              deckBlock = woodStripped;
            }
            if (z === 44 && y >= 15 && y <= 17) {
              isDeck = true;
              deckBlock = woodStripped;
            }

            if (isDeck) {
              setBlock(x, y, z, deckBlock);
            } else {
              // Clear interior space as air
              setBlock(x, y, z, "minecraft:air");
            }
          }
        }
      }
    }
  }

  // --- 3. Keel, Stempost, Bowsprit, and Rudder ---
  // Keel
  for (let z = 12; z <= 51; z++) {
    setBlock(midX, 6, z, darkLog);
  }

  // Stempost / Cutwater
  setBlock(midX, 7, 11, darkLog);
  setBlock(midX, 8, 10, darkLog);
  setBlock(midX, 9, 9, darkLog);
  setBlock(midX, 10, 8, darkLog);
  setBlock(midX, 11, 8, darkLog);
  setBlock(midX, 12, 7, darkLog);
  setBlock(midX, 13, 7, darkLog);
  setBlock(midX, 14, 6, darkLog);

  // Figurehead: Horned Dragon / Demon Beast
  setBlock(midX, 12, 6, goldBlock);
  setBlock(midX, 13, 5, skull);
  setBlock(midX - 1, 13, 6, darkStairs);
  setBlock(midX + 1, 13, 6, darkStairs);

  // Bowsprit jutting North
  const bowspritCoords = [
    [midX, 13, 11], [midX, 13, 10], [midX, 14, 9], [midX, 14, 8],
    [midX, 15, 7], [midX, 15, 6], [midX, 16, 5], [midX, 16, 4],
    [midX, 17, 3], [midX, 17, 2], [midX, 18, 1], [midX, 18, 0]
  ];
  for (const [bx, by, bz] of bowspritCoords) {
    setBlock(bx, by, bz, darkLog);
  }
  setBlock(midX, 17, 0, hangLantern);

  // Bowsprit Jib Rigging & Small triangular jib sail
  for (let jz = 2; jz <= 6; jz++) {
    setBlock(midX, 14, jz, blackWool);
    setBlock(midX, 13, jz + 1, blackWool);
  }
  setBlock(midX, 12, 8, chain);

  // Anchor chains at port & starboard hawseholes
  setBlock(midX - 3, 11, 12, ironBars);
  setBlock(midX - 4, 10, 11, chain);
  setBlock(midX - 5, 9, 10, chain);
  setBlock(midX - 5, 8, 9, chain);
  setBlock(midX - 5, 7, 9, polishedBlackstone);

  setBlock(midX + 3, 11, 12, ironBars);
  setBlock(midX + 4, 10, 11, chain);
  setBlock(midX + 5, 9, 10, chain);
  setBlock(midX + 5, 8, 9, chain);
  setBlock(midX + 5, 7, 9, polishedBlackstone);

  // Rudder at stern
  for (let ry = 4; ry <= 12; ry++) {
    setBlock(midX, ry, 52, darkLog);
    setBlock(midX, ry, 53, darkPlanks);
    if (ry % 3 === 0) {
      setBlock(midX, ry, 52, ironBars);
    }
  }

  // --- 4. Broadside Cannons & Gun Ports ---
  const cannonZList = [16, 20, 24, 28, 32, 36, 40, 44];
  for (const cz of cannonZList) {
    const rad = getHullRadius(11, cz);
    if (rad > 2) {
      const xPort = midX - Math.round(rad);
      const xStar = midX + Math.round(rad);

      // Port Cannon
      setBlock(xPort, 11, cz, dispenserWest);
      setBlock(xPort + 1, 11, cz, polishedBlackstone);
      setBlock(xPort, 12, cz, darkTrapdoor);

      // Starboard Cannon
      setBlock(xStar, 11, cz, dispenserEast);
      setBlock(xStar - 1, 11, cz, polishedBlackstone);
      setBlock(xStar, 12, cz, darkTrapdoor);
    }
  }

  // Swivel guns on waist rails
  const swivelZList = [22, 26, 30, 34];
  for (const sz of swivelZList) {
    const rad = getHullRadius(13, sz);
    const xPort = midX - Math.round(rad);
    const xStar = midX + Math.round(rad);
    setBlock(xPort, 14, sz, dispenserWest);
    setBlock(xStar, 14, sz, dispenserEast);
  }

  // --- 5. Stern Galleries & Captain's Quarters Detail ---
  // Great Cabin Windows at z = 51, y = 15..17
  for (let wx = midX - 3; wx <= midX + 3; wx++) {
    setBlock(wx, 15, 51, ironBars);
    setBlock(wx, 16, 51, ironBars);
  }
  setBlock(midX - 3, 17, 51, goldBlock);
  setBlock(midX + 3, 17, 51, goldBlock);
  setBlock(midX, 17, 51, goldBlock);

  // Sternwalk Balcony at z = 52..53, y = 14
  for (let bx = midX - 3; bx <= midX + 3; bx++) {
    setBlock(bx, 14, 52, darkPlanks);
    setBlock(bx, 14, 53, darkSlab);
    setBlock(bx, 15, 53, darkFence);
  }
  setBlock(midX - 3, 15, 52, darkFence);
  setBlock(midX + 3, 15, 52, darkFence);

  // Sternwalk underside brackets
  for (let bx = midX - 2; bx <= midX + 2; bx += 2) {
    setBlock(bx, 13, 52, darkStairs);
    setBlock(bx, 12, 51, darkStairs);
  }

  // Large Ornate Stern Lanterns
  const sternLanterns = [
    [midX - 3, 17, 54],
    [midX, 19, 54],
    [midX + 3, 17, 54]
  ];
  for (const [lx, ly, lz] of sternLanterns) {
    setBlock(lx, ly + 1, lz - 1, darkFence);
    setBlock(lx, ly + 1, lz, darkFence);
    setBlock(lx, ly, lz, goldBlock);
    setBlock(lx, ly - 1, lz, hangLantern);
  }

  // Captain's Cabin Doorway & Furniture Base
  setBlock(midX, 15, 44, woodDoor);
  setBlock(midX, 16, 44, "minecraft:air");
  setBlock(midX, 15, 45, "minecraft:air");
  setBlock(midX, 16, 45, "minecraft:air");

  // Companionways and Deck Stairs
  // Forecastle access stairs
  setBlock(midX, 11, 19, darkStairs);
  setBlock(midX, 12, 18, darkStairs);
  setBlock(midX, 13, 17, darkStairs);

  // Quarterdeck access stairs
  setBlock(midX - 2, 11, 36, darkStairs);
  setBlock(midX - 2, 12, 37, darkStairs);
  setBlock(midX - 2, 13, 38, darkStairs);
  setBlock(midX + 2, 11, 36, darkStairs);
  setBlock(midX + 2, 12, 37, darkStairs);
  setBlock(midX + 2, 13, 38, darkStairs);

  // Poop deck access stairs
  setBlock(midX - 3, 15, 44, darkStairs);
  setBlock(midX - 3, 16, 45, darkStairs);
  setBlock(midX - 3, 17, 46, darkStairs);
  setBlock(midX + 3, 15, 44, darkStairs);
  setBlock(midX + 3, 16, 45, darkStairs);
  setBlock(midX + 3, 17, 46, darkStairs);

  // Deck fittings: Ship's Wheel, Capstan, Cargo Hatch
  // Ship's Wheel on Poop Deck
  setBlock(midX, 19, 47, darkFence);
  setBlock(midX, 20, 47, darkTrapdoor);

  // Capstan on Waist Deck
  setBlock(midX, 12, 23, darkLog);
  setBlock(midX - 1, 12, 23, darkFence);
  setBlock(midX + 1, 12, 23, darkFence);

  // Cargo Hatch Grate on Waist Deck
  setBlock(midX - 1, 11, 31, darkTrapdoor);
  setBlock(midX, 11, 31, darkTrapdoor);
  setBlock(midX + 1, 11, 31, darkTrapdoor);
  setBlock(midX - 1, 11, 32, darkTrapdoor);
  setBlock(midX, 11, 32, darkTrapdoor);
  setBlock(midX + 1, 11, 32, darkTrapdoor);

  // Ship's Bell on Forecastle
  setBlock(midX, 16, 17, darkFence);
  setBlock(midX, 15, 17, goldBlock);

  // --- 6. The Three Great Masts, Rigging, and Ragged Sails ---
  function buildMast(mx, mz, baseY, topY, crowsNestY) {
    // Mast Trunk
    for (let y = baseY; y <= topY; y++) {
      setBlock(mx, y, mz, darkLog);
      if (y >= 11 && y < crowsNestY) {
        setBlock(mx, y, mz - 1, ladderNorth);
      }
    }

    // Crow's Nest / Fighting Top
    if (crowsNestY > 0) {
      for (let cx = mx - 1; cx <= mx + 1; cx++) {
        for (let cz = mz - 1; cz <= mz + 1; cz++) {
          setBlock(cx, crowsNestY, cz, darkPlanks);
          if (cx === mx - 1 || cx === mx + 1 || cz === mz - 1 || cz === mz + 1) {
            setBlock(cx, crowsNestY + 1, cz, darkFence);
          }
        }
      }
      setBlock(mx, crowsNestY, mz, darkLog);
      setBlock(mx, crowsNestY + 1, mz, darkLog);
    }
  }

  function buildYardAndSail(mx, mz, yardY, halfWidth, sailHeight, hasCrimsonMotif) {
    // Horizontal Yard Spar
    for (let x = mx - halfWidth; x <= mx + halfWidth; x++) {
      setBlock(x, yardY, mz, darkLog);
    }
    setBlock(mx - halfWidth - 1, yardY, mz, darkFence);
    setBlock(mx + halfWidth + 1, yardY, mz, darkFence);

    // Billowed Ragged Sail hanging below yard
    for (let sy = 1; sy <= sailHeight; sy++) {
      const y = yardY - sy;
      const vFrac = sy / sailHeight; // 0 near top, 1 at bottom

      for (let x = mx - halfWidth + 1; x <= mx + halfWidth - 1; x++) {
        const uFrac = (x - (mx - halfWidth + 1)) / (2 * halfWidth - 2);
        // Billow forward (-Z)
        const billow = Math.round(1.3 * Math.sin(Math.PI * uFrac) * Math.sin(Math.PI * vFrac));
        const sz = mz - billow;

        // Ragged bottom tears
        if (sy === sailHeight && ((x + sz) % 3 === 0)) {
          setBlock(x, y, sz, darkFence);
          continue;
        }

        // Color selection: Dread Pirate Emblem
        let block = blackWool;
        if ((x + y) % 5 === 0) block = grayWool;

        if (hasCrimsonMotif) {
          const dx = Math.abs(x - mx);
          const dy = Math.abs(y - (yardY - Math.floor(sailHeight / 2)));
          // Crimson Cross / Skull Icon
          if ((dx === 0 && dy <= 2) || (dy === 0 && dx <= 3) || (dx === 2 && dy === 1)) {
            block = redWool;
          } else if (dx === 1 && dy === 1) {
            block = boneBlock;
          }
        }

        setBlock(x, y, sz, block);
      }
    }
  }

  // --- Foremast (Z = 16) ---
  buildMast(midX, 16, 7, 34, 23);
  buildYardAndSail(midX, 16, 19, 7, 4, false); // Course sail
  buildYardAndSail(midX, 16, 27, 5, 3, false); // Topsail
  buildYardAndSail(midX, 16, 31, 3, 2, false); // Topgallant
  setBlock(midX, 35, 16, redBannerSouth);

  // --- Mainmast (Z = 28) - Flagship Centerpiece ---
  buildMast(midX, 28, 7, 37, 25);
  buildYardAndSail(midX, 28, 20, 9, 5, true);  // Massive course sail with blood crest
  buildYardAndSail(midX, 28, 28, 6, 3, false); // Main topsail
  buildYardAndSail(midX, 28, 33, 4, 2, false); // Main topgallant
  setBlock(midX, 37, 28, blackBannerNorth);
  setBlock(midX, 37, 29, redBannerSouth);

  // --- Mizzenmast (Z = 40) ---
  buildMast(midX, 40, 7, 32, 22);
  buildYardAndSail(midX, 40, 19, 6, 4, false); // Mizzen sail
  buildYardAndSail(midX, 40, 26, 4, 3, false); // Topsail
  setBlock(midX, 33, 40, redBannerSouth);

  // --- Standing Rigging (Shrouds & Stays) ---
  // Forestays & inter-mast stays
  for (let z = 9; z <= 15; z++) {
    const y = Math.round(14 + (z - 9) * (23 - 14) / 6);
    setBlock(midX, y, z, chain);
  }
  for (let z = 17; z <= 27; z++) {
    const y = Math.round(23 + (z - 17) * (25 - 23) / 10);
    setBlock(midX, y, z, chain);
  }
  for (let z = 29; z <= 39; z++) {
    const y = Math.round(25 - (z - 29) * (25 - 22) / 10);
    setBlock(midX, y, z, chain);
  }
  for (let z = 41; z <= 48; z++) {
    const y = Math.round(22 - (z - 41) * (22 - 18) / 7);
    setBlock(midX, y, z, chain);
  }

  // Shrouds (Ratlines) on port and starboard rails
  const mastZShrouds = [16, 28, 40];
  for (const mz of mastZShrouds) {
    const rad = getHullRadius(13, mz);
    const xP = midX - Math.round(rad);
    const xS = midX + Math.round(rad);

    for (let sy = 13; sy <= 21; sy++) {
      const xOffset = (sy - 13) * 0.4;
      setBlock(Math.round(xP + xOffset), sy, mz - 1, darkFence);
      setBlock(Math.round(xP + xOffset), sy, mz + 1, darkFence);
      setBlock(Math.round(xS - xOffset), sy, mz - 1, darkFence);
      setBlock(Math.round(xS - xOffset), sy, mz + 1, darkFence);
    }
  }

  // Deck lanterns for illumination
  setBlock(midX, 15, 14, hangLantern);
  setBlock(midX, 13, 21, hangLantern);
  setBlock(midX, 13, 35, hangLantern);
  setBlock(midX, 16, 39, hangLantern);
  setBlock(midX, 20, 50, hangLantern);

  return {
    name: "Dread Corsair Flagship",
    seatY: seatY,
    anchors: {
      front: [midX, 14, 0],
      gangway: [midX - 5, 11, 28],
      helm: [midX, 19, 47],
      cabin: [midX, 15, 48],
      crow_nest: [midX, 26, 28]
    },
    interiors: [
      {
        min: [midX - 2, 7, 20],
        max: [midX + 2, 9, 35],
        kind: "vault"
      },
      {
        min: [midX - 3, 11, 16],
        max: [midX + 3, 13, 42],
        kind: "hall"
      },
      {
        min: [midX - 3, 15, 45],
        max: [midX + 3, 17, 50],
        kind: "quarters"
      }
    ]
  };
}

