export const envelope = [9, 12, 9];

export default function build(api) {
  const [sizeX, sizeY, sizeZ] = api.size;
  const seatY = 4;

  // Theme roles with safe fallbacks
  const stonePrimary = api.theme?.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:mossy_stone_bricks";
  const stoneStairs = api.theme?.stone?.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme?.stone?.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme?.stone?.wall || "minecraft:stone_brick_wall";

  const woodPlanks = api.theme?.wood?.planks || "minecraft:dark_oak_planks";
  const woodLog = api.theme?.wood?.log || "minecraft:dark_oak_log";
  const woodStairs = api.theme?.wood?.stairs || "minecraft:dark_oak_stairs";
  const woodSlab = api.theme?.wood?.slab || "minecraft:dark_oak_slab";
  const woodFence = api.theme?.wood?.fence || "minecraft:dark_oak_fence";
  const woodTrapdoor = api.theme?.wood?.trapdoor || "minecraft:dark_oak_trapdoor";

  const groundRevetment = api.theme?.ground?.revetment || "minecraft:cobblestone";
  const groundPlinth = api.theme?.ground?.plinth || stonePrimary;
  const groundPavement = api.theme?.ground?.pavement || "minecraft:cobblestone";

  // Helper to attach block states safely
  function withState(blockStr, stateStr) {
    if (!blockStr) return stateStr;
    const base = blockStr.split("[")[0];
    return `${base}[${stateStr}]`;
  }

  // Safe block placement within envelope
  function setBlock(x, y, z, block) {
    if (x >= 0 && x < sizeX && y >= 0 && y < sizeY && z >= 0 && z < sizeZ) {
      api.set(x, y, z, block);
    }
  }

  // Determine instance variation (0 to 5)
  const variant = (api.instance.index !== undefined ? api.instance.index : Math.floor(api.random() * 6)) % 6;

  // 9x9 Bastion Footprint Mask (z from 0 to 8, x from 0 to 8)
  // Local North (-Z) is front facing the strait
  const footprint = [
    // z=0: Front gun-port embrasure lip & prow
    [0, 0, 0, 1, 1, 1, 0, 0, 0],
    // z=1: Front gun deck embrasure wall
    [0, 1, 1, 1, 1, 1, 1, 1, 0],
    // z=2: Forward gun deck
    [1, 1, 1, 1, 1, 1, 1, 1, 1],
    // z=3: Main battery carriage position
    [1, 1, 1, 1, 1, 1, 1, 1, 1],
    // z=4: Bastion center & breech
    [1, 1, 1, 1, 1, 1, 1, 1, 1],
    // z=5: Rear deck & recoil run
    [1, 1, 1, 1, 1, 1, 1, 1, 1],
    // z=6: Munitions and sentry stations
    [1, 1, 1, 1, 1, 1, 1, 1, 1],
    // z=7: Rear wall & entrance arch
    [0, 1, 1, 1, 1, 1, 1, 1, 0],
    // z=8: Landward access steps
    [0, 0, 1, 1, 1, 1, 1, 0, 0]
  ];

  // 1. FOUNDATION & SUB-STRUCTURE (Ground conformity: Rule 6)
  for (let z = 0; z < 9; z++) {
    for (let x = 0; x < 9; x++) {
      if (footprint[z][x] !== 1) continue;

      const rawH = api.heightAt(x, z);
      const groundY = Math.max(0, Math.min(11, seatY + rawH));

      // Build down to terrain/seabed to ensure no hovering sole
      const startY = Math.min(groundY, seatY);
      for (let y = startY; y <= seatY; y++) {
        let mat = stonePrimary;
        if (y <= 1) {
          mat = (api.random() < 0.4) ? groundRevetment : "minecraft:mossy_cobblestone";
        } else if (y <= 3) {
          mat = (api.random() < 0.3) ? stoneAccent : groundPlinth;
        } else {
          mat = (api.random() < 0.25) ? stoneAccent : stonePrimary;
        }
        setBlock(x, y, z, mat);
      }

      // If hillside rises above seat plane, build revetment upward to anchor into slope
      if (groundY > seatY) {
        for (let y = seatY + 1; y <= Math.min(groundY, 5); y++) {
          setBlock(x, y, z, stonePrimary);
        }
      }
    }
  }

  // 2. BASTION PLATFORM & FLOOR (y = 4 and 5)
  for (let z = 1; z <= 7; z++) {
    for (let x = 1; x <= 7; x++) {
      if (footprint[z][x] !== 1) continue;
      // Solid sub-floor
      setBlock(x, 4, z, (api.random() < 0.2) ? stoneAccent : stonePrimary);

      // Deck floor paving at y = 5
      if (x >= 2 && x <= 6 && z >= 2 && z <= 6) {
        // Cannon recoil timber runway down the middle
        if (x === 4 && z >= 2 && z <= 5) {
          setBlock(x, 5, z, woodPlanks);
        } else if ((x === 3 || x === 5) && (z === 3 || z === 4)) {
          setBlock(x, 5, z, withState(woodLog, "axis=z"));
        } else {
          // Cobblestone / stone pavers around deck
          const pave = (api.random() < 0.5) ? groundPavement : stonePrimary;
          setBlock(x, 5, z, pave);
        }
      }
    }
  }

  // Front prow overhang bracket under cannon muzzle at z=0, y=5
  setBlock(3, 5, 0, withState(stoneStairs, "facing=east,half=top"));
  setBlock(4, 5, 0, withState(stoneStairs, "facing=south,half=top"));
  setBlock(5, 5, 0, withState(stoneStairs, "facing=west,half=top"));

  // 3. PARAPET WALLS & EMBRASURES (y = 5 and 6)
  // Low perimeter base at y = 5
  for (let z = 1; z <= 7; z++) {
    for (let x = 1; x <= 7; x++) {
      const isPerimeter = (x === 1 || x === 7 || z === 1 || z === 7);
      if (isPerimeter && footprint[z][x] === 1) {
        // Leave rear door open at (4, 5, 7)
        if (x === 4 && z === 7) {
          setBlock(x, 5, z, groundPavement);
          continue;
        }
        // Front embrasure throat
        if (z === 1 && x === 4) {
          setBlock(x, 5, z, withState(stoneStairs, "facing=north,half=bottom"));
        } else if (z === 1 && x === 3) {
          setBlock(x, 5, z, withState(stoneStairs, "facing=west,half=bottom"));
        } else if (z === 1 && x === 5) {
          setBlock(x, 5, z, withState(stoneStairs, "facing=east,half=bottom"));
        } else {
          setBlock(x, 5, z, (api.random() < 0.25) ? stoneAccent : stonePrimary);
        }
      }
    }
  }

  // Parapet Wall Height at y = 6
  // Flanks and rear parapets
  setBlock(1, 6, 2, stonePrimary);
  setBlock(1, 6, 3, stoneWall);
  setBlock(1, 6, 4, stonePrimary);
  setBlock(1, 6, 5, stoneWall);
  setBlock(1, 6, 6, stonePrimary);

  setBlock(7, 6, 2, stonePrimary);
  setBlock(7, 6, 3, stoneWall);
  setBlock(7, 6, 4, stonePrimary);
  setBlock(7, 6, 5, stoneWall);
  setBlock(7, 6, 6, stonePrimary);

  // Front cheeks flanking the cannon port
  setBlock(1, 6, 1, stonePrimary);
  setBlock(2, 6, 1, stonePrimary);
  setBlock(3, 6, 1, withState(stoneStairs, "facing=west,half=bottom"));
  // (4, 6, 1) is open embrasure for cannon barrel
  setBlock(5, 6, 1, withState(stoneStairs, "facing=east,half=bottom"));
  setBlock(6, 6, 1, stonePrimary);
  setBlock(7, 6, 1, stonePrimary);

  // Rear wall parapets
  setBlock(2, 6, 7, stonePrimary);
  setBlock(3, 6, 7, withState(stoneStairs, "facing=south,half=bottom"));
  // (4, 6, 7) is open doorway archway
  setBlock(5, 6, 7, withState(stoneStairs, "facing=south,half=bottom"));
  setBlock(6, 6, 7, stonePrimary);

  // 4. MERLONS & CRENELLATIONS (y = 7)
  const merlonCoords = [
    [1, 1], [3, 1], [5, 1], [7, 1],
    [1, 3], [1, 5], [7, 3], [7, 5],
    [1, 7], [3, 7], [5, 7], [7, 7]
  ];
  for (const [mx, mz] of merlonCoords) {
    // Battle damage variation on instance 4
    if (variant === 4 && mx === 3 && mz === 1) {
      setBlock(mx, 7, mz, withState(stoneStairs, "facing=north,half=bottom"));
      continue;
    }
    setBlock(mx, 7, mz, (api.random() < 0.25) ? stoneAccent : stonePrimary);
    setBlock(mx, 8, mz, withState(stoneSlab, "type=bottom"));
  }

  // 5. REAR ACCESS STEPS (z = 7 and 8)
  const rearH = api.heightAt(4, 8);
  const rearGround = Math.max(0, seatY + rearH);
  setBlock(4, 5, 8, withState(stoneStairs, "facing=north,half=bottom"));
  setBlock(3, 5, 8, withState(stoneStairs, "facing=east,half=bottom"));
  setBlock(5, 5, 8, withState(stoneStairs, "facing=west,half=bottom"));
  if (rearGround < 4) {
    setBlock(4, 4, 8, withState(stoneStairs, "facing=north,half=bottom"));
  }

  // 6. THE HEAVY SHORE CANNON (Facing North = -Z)
  // Carriage Wheels & Bed (y = 5 and 6)
  setBlock(3, 5, 3, withState(woodStairs, "facing=north,half=bottom"));
  setBlock(5, 5, 3, withState(woodStairs, "facing=north,half=bottom"));
  setBlock(3, 5, 4, withState(woodStairs, "facing=south,half=bottom"));
  setBlock(5, 5, 4, withState(woodStairs, "facing=south,half=bottom"));
  setBlock(4, 5, 4, withState(woodStairs, "facing=south,half=top")); // Carriage wedge

  // Carriage Side Cheeks / Trunnion brackets at y = 6
  setBlock(3, 6, 3, withState(woodTrapdoor, "facing=west,half=bottom,open=true"));
  setBlock(5, 6, 3, withState(woodTrapdoor, "facing=east,half=bottom,open=true"));
  setBlock(3, 6, 4, withState(woodTrapdoor, "facing=west,half=bottom,open=true"));
  setBlock(5, 6, 4, withState(woodTrapdoor, "facing=east,half=bottom,open=true"));

  // Heavy Metal Cannon Barrel
  if (variant === 1) {
    // Heavy Short Mortar / Bombard
    setBlock(4, 6, 4, "minecraft:polished_blackstone");
    setBlock(4, 6, 3, "minecraft:netherite_block");
    setBlock(4, 6, 2, "minecraft:polished_blackstone");
    setBlock(4, 6, 1, "minecraft:cauldron");
    setBlock(4, 7, 1, "minecraft:iron_bars");
  } else if (variant === 0 || variant === 5) {
    // Great Shore Culverin (Long barrel extending forward over strait)
    setBlock(4, 6, 4, "minecraft:polished_blackstone");
    setBlock(4, 6, 3, "minecraft:deepslate_tiles");
    setBlock(4, 6, 2, "minecraft:polished_blackstone");
    setBlock(4, 6, 1, "minecraft:deepslate_tiles");
    setBlock(4, 6, 0, "minecraft:dispenser[facing=north]");
    // Touchhole lever / vent
    setBlock(4, 7, 3, "minecraft:lever[face=floor,facing=north]");
  } else {
    // Naval 32-Pounder Bastion Gun
    setBlock(4, 6, 4, "minecraft:polished_blackstone");
    setBlock(4, 6, 3, "minecraft:polished_blackstone");
    setBlock(4, 6, 2, "minecraft:deepslate_tiles");
    setBlock(4, 6, 1, "minecraft:dispenser[facing=north]");
    // Touchhole
    setBlock(4, 7, 3, "minecraft:stone_button[face=floor,facing=north]");
  }

  // Heavy Breech Recoil Chains
  setBlock(3, 6, 4, "minecraft:chain[axis=x]");
  setBlock(5, 6, 4, "minecraft:chain[axis=x]");

  // 7. BATTERY PROPS (Ammunition, Gunpowder, Tools)
  // Gunpowder kegs (Barrels / TNT)
  setBlock(2, 5, 4, "minecraft:barrel[facing=up]");
  setBlock(2, 5, 5, (variant === 4 || variant === 1) ? "minecraft:tnt" : "minecraft:barrel[facing=up]");
  setBlock(6, 5, 5, "minecraft:barrel[facing=up]");

  // Shot Pyramids / Iron Cannonballs
  setBlock(6, 5, 3, "minecraft:coal_block");
  setBlock(6, 5, 4, "minecraft:coal_block");
  setBlock(6, 6, 3, withState(stoneSlab, "type=bottom"));

  // Artillery Ramrod / Sponge leaning station
  setBlock(2, 6, 2, woodFence);
  setBlock(2, 7, 2, "minecraft:torch");

  // 8. UNIQUE SUPERSTRUCTURES PER INSTANCE (Rules 1 & 9)
  if (variant === 0) {
    // Instance 0: Signal Beacon Post & Brass Lantern
    setBlock(1, 7, 6, stoneWall);
    setBlock(1, 8, 6, stoneWall);
    setBlock(1, 9, 6, "minecraft:campfire[lit=true]");
    setBlock(1, 10, 6, withState(stoneStairs, "facing=south,half=top"));
    setBlock(7, 7, 6, woodFence);
    setBlock(7, 8, 6, woodFence);
    setBlock(7, 9, 6, "minecraft:lantern[hanging=false]");
  } else if (variant === 1) {
    // Instance 1: Timber Pavise & Lookout Station
    setBlock(7, 7, 5, woodFence);
    setBlock(7, 8, 5, woodFence);
    setBlock(7, 7, 6, woodFence);
    setBlock(7, 8, 6, woodFence);
    setBlock(7, 9, 5, withState(woodStairs, "facing=north,half=bottom"));
    setBlock(7, 9, 6, withState(woodStairs, "facing=south,half=bottom"));
    setBlock(6, 8, 6, "minecraft:lantern[hanging=true]");
  } else if (variant === 2) {
    // Instance 2: Heavy Munitions Derrick / Crane for Hoisting Powder
    setBlock(6, 6, 5, woodLog);
    setBlock(6, 7, 5, woodLog);
    setBlock(6, 8, 5, woodLog);
    setBlock(6, 9, 5, withState(woodStairs, "facing=south,half=top"));
    setBlock(6, 9, 6, woodFence);
    setBlock(6, 8, 6, "minecraft:chain[axis=y]");
    setBlock(6, 7, 6, "minecraft:cauldron"); // Hoist basket
  } else if (variant === 3) {
    // Instance 3: Weather-Proof Timber Rafter Canopy over Gun Crew
    setBlock(2, 7, 5, woodFence);
    setBlock(2, 8, 5, woodFence);
    setBlock(6, 7, 5, woodFence);
    setBlock(6, 8, 5, woodFence);
    // Roof Beam
    for (let rx = 2; rx <= 6; rx++) {
      setBlock(rx, 9, 5, withState(woodSlab, "type=bottom"));
    }
    setBlock(3, 9, 4, withState(woodStairs, "facing=north,half=bottom"));
    setBlock(4, 9, 4, withState(woodStairs, "facing=north,half=bottom"));
    setBlock(5, 9, 4, withState(woodStairs, "facing=north,half=bottom"));
    setBlock(4, 8, 5, "minecraft:lantern[hanging=true]");
  } else if (variant === 4) {
    // Instance 4: Corsair Signal Mast & Black Pennant
    setBlock(6, 6, 6, woodLog);
    setBlock(6, 7, 6, woodFence);
    setBlock(6, 8, 6, woodFence);
    setBlock(6, 9, 6, woodFence);
    setBlock(6, 10, 6, woodFence);
    setBlock(6, 11, 6, woodFence);
    // Cross yardarm
    setBlock(5, 10, 6, woodFence);
    setBlock(7, 10, 6, woodFence);
    // Pirate battle pennant blowing north toward the enemy
    setBlock(6, 10, 5, "minecraft:black_wool");
    setBlock(6, 10, 4, "minecraft:black_wool");
    setBlock(6, 9, 5, "minecraft:red_wool");
  } else if (variant === 5) {
    // Instance 5: Mystic Soul-Fire Harbor Beacon Turret
    setBlock(1, 7, 6, stonePrimary);
    setBlock(2, 7, 6, stoneWall);
    setBlock(1, 8, 6, stonePrimary);
    setBlock(1, 9, 6, "minecraft:soul_campfire[lit=true]");
    setBlock(0, 9, 6, "minecraft:iron_bars");
    setBlock(2, 9, 6, "minecraft:iron_bars");
    setBlock(1, 9, 5, "minecraft:iron_bars");
    setBlock(1, 9, 7, "minecraft:iron_bars");
    setBlock(1, 10, 6, withState(stoneSlab, "type=bottom"));
  }

  return {
    name: "coastal_defense_turret",
    seatY: seatY,
    anchors: {
      front: [4, 6, 0], // Rule 12: Points North toward contested waters
      door: [4, 4, 8]   // Landward supply entrance
    }
  };
}
